    .replace(/(Bearer\s+)[A-Za-z0-9._~+/-]+=*(\s|$)/gi, "$1***$2")
    .replace(/("?(authorization|api[_-]?key|token|secret)"?\s*[:=]\s*"?)[^",\s}]+/gi, "$1***");
}

