26: async function rpc<T>(cfg: HttpBackendConfig, name: string, body: Record<string, unknown>): Promise<T> {
27:   const base = cfg.url.replace(/\/$/, "");
28:   const controller = new AbortController();
29:   const timer = setTimeout(() => controller.abort(), cfg.timeoutMs ?? 15_000);
30:   try {
31:     const res = await fetch(`${base}/rpc/${name}`, {
32:       method: "POST",
33:       headers: {
34:         "Content-Type": "application/json",
35:         ...(cfg.token ? { Authorization: `Bearer ${cfg.token}` } : {}),
36:       },
37:       body: JSON.stringify(body),
38:       signal: controller.signal,
39:     });
40:     if (res.status === 401 || res.status === 403) {
41:       throw new EngineError("HTTP_BACKEND_AUTH", `HTTP backend refused ${name} with status ${res.status}; check the configured token and project access.`);
42:     }
43:     if (!res.ok) {
44:       throw new EngineError("HTTP_BACKEND_PROTOCOL", `HTTP backend ${name} failed with status ${res.status} at ${redactUrl(base)}.`);
45:     }
46:     try {
47:       return (await res.json()) as T;
48:     } catch {
49:       throw new EngineError("HTTP_BACKEND_PROTOCOL", `HTTP backend ${name} returned malformed JSON.`);
50:     }
51:   } catch (error) {
52:     if (error instanceof EngineError) throw error;
53:     throw new EngineError(
54:       "HTTP_BACKEND_UNREACHABLE",
55:       `HTTP backend unreachable at ${redactUrl(cfg.url)}: ${error instanceof Error ? `${error.name}: ${error.message.slice(0, 160)}` : String(error).slice(0, 160)}`,
56:     );
57:   } finally {
58:     clearTimeout(timer);
59:   }
60: }
