        segment += ch;
      } else if (ch === '"' || ch === "'" || ch === "`") {
        s = ch;
        segment += ch;
      } else if (ch === "{" || ch === "[") {
        d += 1;
        segment += ch;
      } else if (ch === "}" || ch === "]") {
        d -= 1;
        segment += ch;
      } else if (ch === "," && d === 0) {
        segments.push(segment);
        segment = "";
      } else {
        segment += ch;
      }
      p = ch;
    }
    segments.push(segment);
    for (const seg of segments) {
