  let content: string;
  try {
    content = await fs.readFile(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }
  const endsNewline = content.endsWith("\n");
  const lines = content.split("\n");
  const out: T[] = [];
